import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Get your first reply","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),n={name:"guide/quickstart.md"};function h(l,a,r,p,o,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="get-your-first-reply" tabindex="-1">Get your first reply <a class="header-anchor" href="#get-your-first-reply" aria-label="Permalink to &quot;Get your first reply&quot;">​</a></h1><p>You will start the gateway locally, create an agent, and verify its connection before adding more channels.</p><h2 id="_1-check-the-prerequisites" tabindex="-1">1. Check the prerequisites <a class="header-anchor" href="#_1-check-the-prerequisites" aria-label="Permalink to &quot;1. Check the prerequisites&quot;">​</a></h2><p>Use Node.js 22 or newer, an installed and authenticated Claude Code CLI with channels support (the repository requires 2.1.0 or newer), and Bun for the MCP subprocess.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Run Claude Code directly once to confirm authentication under the same operating-system account that will run the gateway. If the executable is outside that account&#39;s PATH, set <code>CLAUDE_BIN</code> to its absolute path.</p><h2 id="_2-install-and-start" tabindex="-1">2. Install and start <a class="header-anchor" href="#_2-install-and-start" aria-label="Permalink to &quot;2. Install and start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @0xmaxma/claude-gateway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>The gateway runs in the foreground. Keep this terminal open and use another terminal for the following commands. Installation uses Bun to install MCP dependencies. Platforms without a compatible prebuilt <code>node-pty</code> binary may need native build tools.</p><p>On first start, the gateway creates <code>~/.claude-gateway/config.json</code> with an empty agent list and a random admin key. The gateway stores the key in that file with mode <code>0600</code> and prints only its suffix; the local CLI reads it automatically. An existing configuration is retained.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:10850/health</span></span></code></pre></div><p>The health endpoint should return <code>{&quot;status&quot;:&quot;ok&quot;}</code>. It confirms liveness, not that an agent or its provider works. The port defaults to <code>10850</code>; adjust the URL if you set <code>PORT</code>.</p><h2 id="_3-create-an-agent" tabindex="-1">3. Create an agent <a class="header-anchor" href="#_3-create-an-agent" aria-label="Permalink to &quot;3. Create an agent&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Describe the agent in the interactive wizard, review the generated workspace files, and accept them. You can connect Telegram or Discord during creation. The agent hot-reloads without restarting the gateway.</p><h2 id="_4-pair-and-send-a-message" tabindex="-1">4. Pair and send a message <a class="header-anchor" href="#_4-pair-and-send-a-message" aria-label="Permalink to &quot;4. Pair and send a message&quot;">​</a></h2><p>For Telegram, send a private message to the bot to obtain a pairing code. Replace <code>assistant</code> with the agent ID you created:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pending</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> approve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --channel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_CODE</span></span></code></pre></div><p>Send “Hello, introduce yourself.” A reply confirms inbound delivery, access approval, model execution, and outbound delivery. If it stays silent, work through <a href="./channels.html">channel checks</a> and <a href="./troubleshooting.html">troubleshooting</a>.</p><p>Next, <a href="./orchestration.html">enable orchestration</a>, optionally <a href="./voice.html">configure voice</a>, then <a href="./operations.html">run it as a service</a> or <a href="./agents.html">customize the agent</a>.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/config/bootstrap.ts" target="_blank" rel="noreferrer">first-run implementation</a>.</p>`,21)])])}const g=s(n,[["render",h]]);export{k as __pageData,g as default};
